<template>
  <div class="page-container knowledge-page">
    <section class="knowledge-hero">
      <div><h1 class="page-title">专业知识库</h1></div>
      <el-button type="primary" size="large" @click="createKb"><el-icon><Plus /></el-icon>新建知识库</el-button>
    </section>

    <section class="search-hero surface">
      <div class="search-mark"><el-icon><Search /></el-icon></div><div class="search-copy"><strong>查找专业依据</strong><span>输入问题、法规名称或标准号，查看可直接引用的原文片段</span></div><el-input v-model="query" size="large" placeholder="例如：废气排放执行什么标准？" @keyup.enter="runSearch" /><el-button type="primary" :loading="searching" @click="runSearch">查找依据</el-button>
    </section>

    <section class="knowledge-layout">
      <aside class="library-pane surface">
        <div class="pane-header"><div><h3>知识库</h3></div><button @click="createKb"><el-icon><Plus /></el-icon></button></div>
        <div class="library-list"><div v-for="base in bases" :key="base.id" class="library-row" :class="{ active: selectedBase?.id === base.id }"><button class="library-select" @click="selectBase(base)"><span class="library-icon"><el-icon><Collection /></el-icon></span><span class="library-copy"><strong>{{ base.name }}</strong><small>{{ base.document_count }} 份资料 · {{ base.scope === 'system' ? '系统共享' : '当前工作区' }}</small></span><el-icon><ArrowRight /></el-icon></button><button v-if="base.scope !== 'system'" class="library-delete" title="删除知识库" aria-label="删除知识库" @click.stop="deleteKb(base)"><el-icon><Delete /></el-icon></button></div><el-empty v-if="!bases.length" description="还没有知识库" :image-size="70" /></div>
        <div class="library-tip"><el-icon><Lock /></el-icon><p><strong>资料访问安全</strong><span>工作区资料与其他企业隔离。</span></p></div>
      </aside>

      <main class="documents-pane surface">
        <header class="documents-header"><div><h2>{{ selectedBase?.name || '未选择知识库' }}</h2><p>{{ selectedBase ? `共 ${documents.length} 份资料，${indexedCount} 份可用于检索和报告生成` : '—' }}</p></div><el-button v-if="selectedBase" type="primary" @click="uploadDialog = true"><el-icon><Upload /></el-icon>上传资料</el-button></header>
        <div v-if="selectedBase" class="document-summary"><span><b>{{ documents.length }}</b>全部资料</span><span><b>{{ indexedCount }}</b>已准备好</span><span><b>{{ processingCount }}</b>待处理</span></div>
        <div v-if="selectedBase" class="document-table"><el-table :data="documents"><el-table-column label="资料名称" min-width="230"><template #default="scope"><div class="doc-name"><span><el-icon><Document /></el-icon></span><div><strong>{{ scope.row.title }}</strong><small v-if="scope.row.document_number">{{ scope.row.document_number }}</small></div></div></template></el-table-column><el-table-column label="资料类型" width="130"><template #default="scope">{{ documentTypeLabel(scope.row.document_type) }}</template></el-table-column><el-table-column label="准备状态" width="145"><template #default="scope"><el-tag :type="scope.row.index_status === 'indexed' ? 'success' : 'warning'">{{ indexStatusLabel(scope.row.index_status) }}</el-tag></template></el-table-column><el-table-column label="可引用内容" width="110"><template #default="scope">{{ scope.row.chunk_count }} 个片段</template></el-table-column><el-table-column label="操作" width="165" align="right"><template #default="scope"><el-button link type="primary" @click="process(scope.row)">{{ scope.row.index_status === 'indexed' ? '重新处理' : '开始处理' }}</el-button><el-button link @click="showChunks(scope.row)">查看原文</el-button></template></el-table-column></el-table></div>
        <div v-if="selectedBase && !documents.length" class="upload-empty"><span><el-icon><UploadFilled /></el-icon></span><h3>上传第一份专业资料</h3><p>支持 PDF、Word 等文件，处理后即可用于知识检索和报告编制。</p><el-button type="primary" @click="uploadDialog = true">选择文件</el-button></div>
        <el-empty v-if="!selectedBase" description="暂无内容" />
      </main>
    </section>

    <section v-if="searched" class="results surface">
      <header><div><h2>“{{ lastQuery }}”的专业依据</h2></div><span>{{ results.length }} 条带来源内容</span></header>
      <div v-for="(result,index) in results" :key="result.chunk_id" class="result-card"><div class="result-index">{{ String(index+1).padStart(2,'0') }}</div><div class="result-body"><div class="result-title"><strong>{{ result.document_title }}</strong><el-tag size="small">{{ sourceStatusLabel(result.status) }}</el-tag><span>{{ result.document_number }}</span></div><p class="result-location">{{ result.section_path?.join(' / ') || result.section_title || '正文' }} · {{ result.article_number ? `第${result.article_number}条` : '' }} {{ result.page_start ? `第 ${result.page_start} 页` : '位置未标注' }}</p><p class="result-content">{{ result.content }}</p><footer><span>综合相关度 {{ (result.final_score * 100).toFixed(1) }}%</span><button @click="copyText(result.content)"><el-icon><CopyDocument /></el-icon>复制原文</button></footer></div></div><el-empty v-if="!results.length" description="没有找到匹配的专业依据，请尝试更换关键词" />
    </section>

    <el-dialog v-model="uploadDialog" title="上传专业资料" width="580px"><div class="dialog-intro">上传后系统会自动提取正文、拆分可引用内容，并建立语义检索索引。</div><el-form label-position="top"><el-form-item label="选择文件"><el-upload drag :auto-upload="false" :limit="1" :on-change="onFileChange" :on-remove="() => file = null"><el-icon class="el-icon--upload"><UploadFilled /></el-icon><div class="el-upload__text">拖入文件，或<em>点击选择</em></div></el-upload></el-form-item><el-form-item label="资料标题"><el-input v-model="metadata.title" placeholder="系统会默认使用文件名" /></el-form-item><div class="form-row"><el-form-item label="资料类型"><el-select v-model="metadata.document_type"><el-option label="法规/规章" value="law" /><el-option label="国家标准" value="national_standard" /><el-option label="技术导则" value="technical_guideline" /><el-option label="政策文件" value="policy" /><el-option label="内部资料" value="internal_document" /><el-option label="其他" value="other" /></el-select></el-form-item><el-form-item label="标准号"><el-input v-model="metadata.document_number" placeholder="如 HJ 2.2-2018" /></el-form-item></div><el-form-item label="有效状态"><el-select v-model="metadata.status"><el-option label="待确认" value="unknown" /><el-option label="有效" value="active" /><el-option label="已废止" value="repealed" /><el-option label="已替代" value="superseded" /></el-select></el-form-item></el-form><template #footer><el-button @click="uploadDialog=false">取消</el-button><el-button type="primary" :loading="uploading" @click="upload">上传并开始处理</el-button></template></el-dialog>
    <el-dialog v-model="chunkDialog" title="可引用原文" width="800px"><el-table :data="chunks" max-height="580"><el-table-column prop="chunk_index" label="#" width="54" /><el-table-column label="原文位置" width="190"><template #default="scope">{{ scope.row.section_path?.join(' / ') || scope.row.section_title || '正文' }}<br/><small>{{ scope.row.article_number ? `第${scope.row.article_number}条` : '' }} {{ scope.row.page_start ? `第${scope.row.page_start}页` : '' }}</small></template></el-table-column><el-table-column prop="content" label="原文内容" min-width="430" /></el-table></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowRight, Collection, CopyDocument, Delete, Document, Lock, Plus, Search, Upload, UploadFilled } from '@element-plus/icons-vue'
import { createKnowledgeBase, deleteKnowledgeBase, listKnowledgeBases, listKnowledgeChunks, listKnowledgeDocuments, processKnowledgeDocument, searchKnowledge, uploadKnowledgeDocument } from '../api/knowledge'
import type { KnowledgeBase, KnowledgeChunk, KnowledgeDocument, KnowledgeSearchResult } from '../types'
const bases=ref<KnowledgeBase[]>([]);const selectedBase=ref<KnowledgeBase|null>(null);const documents=ref<KnowledgeDocument[]>([]);const chunks=ref<KnowledgeChunk[]>([]);const results=ref<KnowledgeSearchResult[]>([]);const query=ref('');const lastQuery=ref('');const searched=ref(false);const searching=ref(false);const uploadDialog=ref(false);const chunkDialog=ref(false);const uploading=ref(false);const file=ref<File|null>(null);const metadata=reactive({title:'',document_type:'other',document_number:'',status:'unknown'})
const indexedCount=computed(()=>documents.value.filter((item)=>item.index_status==='indexed').length);const processingCount=computed(()=>documents.value.length-indexedCount.value)
async function loadBases(){bases.value=await listKnowledgeBases();if(!selectedBase.value&&bases.value.length)await selectBase(bases.value[0])}async function selectBase(base:KnowledgeBase){selectedBase.value=base;documents.value=await listKnowledgeDocuments(base.id)}
async function createKb(){const name=window.prompt('请输入知识库名称');if(!name?.trim())return;await createKnowledgeBase({name:name.trim(),scope:'private'});ElMessage.success('知识库已创建');await loadBases()}
async function deleteKb(base: KnowledgeBase){try{await ElMessageBox.confirm(`删除“${base.name}”后，其中的资料和检索内容将不再显示，确认删除吗？`,'删除知识库',{type:'warning',confirmButtonText:'确认删除',cancelButtonText:'取消'});await deleteKnowledgeBase(base.id);ElMessage.success('知识库已删除');selectedBase.value=null;documents.value=[];await loadBases()}catch(error){if(error==='cancel'||error==='close')return;ElMessage.error(error instanceof Error?error.message:'知识库删除失败，请稍后重试')}}
function onFileChange(item:{raw?:File}){file.value=item.raw||null;if(!metadata.title&&file.value)metadata.title=file.value.name.replace(/\.[^.]+$/,'')}
async function upload(){if(!selectedBase.value||!file.value)return ElMessage.warning('请先选择要上传的文件');uploading.value=true;try{const document=await uploadKnowledgeDocument(selectedBase.value.id,file.value,{...metadata,category_codes:[]});ElMessage.success('上传成功，正在准备检索内容');uploadDialog.value=false;file.value=null;await processKnowledgeDocument(document.id);await selectBase(selectedBase.value)}catch(error){ElMessage.error(error instanceof Error?error.message:'上传处理失败')}finally{uploading.value=false}}
async function process(document:KnowledgeDocument){try{await processKnowledgeDocument(document.id);ElMessage.success('资料已处理，可以用于检索和生成报告');if(selectedBase.value)await selectBase(selectedBase.value)}catch(error){ElMessage.error(error instanceof Error?error.message:'处理失败')}}async function showChunks(document:KnowledgeDocument){chunks.value=await listKnowledgeChunks(document.id);chunkDialog.value=true}
async function runSearch(){if(!query.value.trim())return ElMessage.warning('请输入要查找的问题或关键词');searching.value=true;searched.value=true;lastQuery.value=query.value.trim();try{const data=await searchKnowledge({query:lastQuery.value,knowledge_base_ids:selectedBase.value?[selectedBase.value.id]:[],top_k:10});results.value=data.results}catch(error){ElMessage.error(error instanceof Error?error.message:'检索失败')}finally{searching.value=false}}
async function copyText(text:string){await navigator.clipboard.writeText(text);ElMessage.success('原文已复制')}
function documentTypeLabel(type:string){return({law:'法规/规章',regulation:'法规/规章',national_standard:'国家标准',technical_guideline:'技术导则',policy:'政策文件',emergency_plan:'应急预案',internal_document:'内部资料',case_study:'案例资料',other:'其他'}as Record<string,string>)[type]||'其他资料'}
function indexStatusLabel(status:string){return({pending:'等待处理',chunking:'正在整理正文',chunked:'正文已整理',embedding:'正在建立检索能力',indexed:'已准备好',partial:'部分可用',failed:'处理失败'}as Record<string,string>)[status]||'处理中'}
function sourceStatusLabel(status:string){return({active:'现行有效',repealed:'已废止',expired:'已过期',superseded:'已替代',unknown:'待确认',draft:'草稿'}as Record<string,string>)[status]||'有效'}onMounted(loadBases)
</script>

