font-size:9px}.result-content{margin:0;color:#3d3d40;font-size:12px;line-height:1.8;white-space:pre-wrap}.result-body footer{display:flex;justify-content:space-between;align-items:center;margin-top:11px;color:#86868b;font-size:9px}.result-body footer button{display:flex;align-items:center;gap:4px;border:0;background:transparent;color:#0071e3;cursor:pointer;font-size:9px}.dialog-intro{margin:-5px 0 18px;color:#6e6e73;font-size:11px}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.form-row .el-select{width:100%}@media(max-width:1050px){.search-copy,.search-mark{display:none}.knowledge-layout{grid-template-columns:225px minmax(0,1fr)}}@media(max-width:750px){.knowledge-hero,.search-hero{align-items:flex-start;flex-direction:column}.search-hero .el-input,.search-hero .el-button{width:100%}.knowledge-layout{grid-template-columns:1fr}.library-pane{position:static;min-height:auto}.form-row{grid-template-columns:1fr}}
